-- Rollback fixtures only. Written, not executed or applied to a live database.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public,extensions;
grant usage on schema extensions to anon,authenticated;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_depend d on d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e'
 join pg_extension e on e.oid = d.refobjid where e.extname = 'pgtap'
 loop execute format('grant execute on function %s to anon,authenticated',f);end loop;
end;$$;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,is_anonymous,raw_user_meta_data)
 select ('39000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'tier-pub-' || n || '@example.test',now(),false,'{"role":"admin"}' from generate_series(1,3) n;
-- Local transactional fixtures only: shared Auth identities do not auto-enroll.
insert into public.toon_profiles(id) select id from auth.users where id::text like '39000000-0000-4000-8000-%' on conflict(id) do nothing;
insert into public.toon_user_settings(user_id) select id from public.toon_profiles where id::text like '39000000-0000-4000-8000-%' on conflict(user_id) do nothing;
insert into toon_private.toon_user_access(user_id) select id from public.toon_profiles where id::text like '39000000-0000-4000-8000-%' on conflict(user_id) do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)
 select ('49000000-0000-4000-8000-' || right(id::text,12))::uuid,id,now(),now() from auth.users where id::text like '39000000-%';
update public.toon_profiles set username = 'tier_pub_' || right(id::text,1),display_name = '[테스트] 게시',onboarding_completed_at = now() where id::text like '39000000-%';
update toon_private.toon_user_access set status = 'active',role = case when right(user_id::text,1) = '1' then 'admin'::public.toon_user_role else 'user'::public.toon_user_role end where user_id::text like '39000000-%';
insert into toon_private.toon_consent_records(user_id,policy_kind,version)
 select p.id,k,'2026-10-02-preview' from public.toon_profiles p cross join unnest(array['terms','privacy','age_14']) k where p.id::text like '39000000-%';
insert into public.toon_works(id,slug,title,age_rating,catalogue_status)
 select ('59000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'tier-pub-' || n,'[테스트] 게시 작품 ' || n,'all','published' from generate_series(1,3) n;
insert into public.toon_work_platforms(work_id,platform_id,official_url,age_rating,verified_at)
 select w.id,p.id,'https://comic.naver.com/toonshelf-test-only/' || w.slug,'all',now() from public.toon_works w cross join public.toon_platforms p where w.id::text like '59000000-%' and p.code = 'naver_webtoon';
create function public.toon_test_tier_pub_payload() returns jsonb language sql set search_path = '' as $$select '{"title":"publication-spoiler-secret","description":"snapshot-description","tags":["snapshot-tag"],"rows":[{"id":"69000000-0000-4000-8000-000000000001","label":"S custom","colorToken":"S","canonicalTier":null},{"id":"69000000-0000-4000-8000-000000000002","label":"A","colorToken":"A","canonicalTier":"A"}],"placements":[{"workId":"59000000-0000-4000-8000-000000000001","rowId":"69000000-0000-4000-8000-000000000001","position":0},{"workId":"59000000-0000-4000-8000-000000000002","rowId":"69000000-0000-4000-8000-000000000002","position":0},{"workId":"59000000-0000-4000-8000-000000000003","rowId":null,"position":0}]}'::jsonb;$$;
create function public.toon_test_tier_envelope(p_hash text) returns jsonb language sql set search_path = '' as $$select jsonb_build_object('hash',repeat(p_hash,64),'ciphertext',repeat('b',118),'nonce',repeat('c',24));$$;
grant execute on function public.toon_test_tier_pub_payload(),public.toon_test_tier_envelope(text) to authenticated;
select ok(not has_table_privilege('anon','public.toon_tier_list_publications','SELECT'),'Anonymous has no raw publication SELECT');
select ok(not has_table_privilege('authenticated','public.toon_tier_list_publications','SELECT'),'Owners also use current-reader RPCs');
select ok(not has_table_privilege('authenticated','toon_private.toon_tier_share_tokens','SELECT'),'No direct encrypted token SELECT');
select ok(not has_function_privilege('authenticated','toon_private.toon_tier_put_token(uuid,jsonb)','EXECUTE'),'No direct token helper access');
select set_config('request.jwt.claims','{"sub":"39000000-0000-4000-8000-000000000002","session_id":"49000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select set_config('tier_pub.id',public.toon_create_tier_draft(public.toon_test_tier_pub_payload(),null)::text,true);
