select throws_ok($$select public.toon_publish_tier_list(current_setting('tier_pub.id')::uuid,1,1,current_setting('tier_pub.preview')::jsonb->>'fingerprint','public',true,null,false)$$,'P0001','VALIDATION_ERROR','Publication requires explicit confirmation');
