select is(public.toon_save_tier_draft(current_setting('tier_pub.id')::uuid,1,jsonb_set(public.toon_test_tier_pub_payload(),'{title}','"autosave-private-secret"'))->>'version','2','Autosave only changes draft');
select throws_ok($$select public.toon_publish_tier_list(current_setting('tier_pub.id')::uuid,1,2,current_setting('tier_pub.preview')::jsonb->>'fingerprint','public',true,null,true)$$,'P0001','CONFLICT','Stale saved preview cannot be published');
reset role;
