select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is(public.toon_get_tier_publication(current_setting('tier_pub.id')::uuid,null,false,null)->'body','null'::jsonb,'Spoiler body omitted on initial read');
select ok(public.toon_list_public_tiers(1)::text !~ 'publication-spoiler-secret|snapshot-description|snapshot-tag','Public list has no spoiler text');
select is(public.toon_get_tier_publication(current_setting('tier_pub.id')::uuid,null,true,2)->'body'->>'title','publication-spoiler-secret','Saved draft changes do not replace publication');
select is(public.toon_get_tier_publication(current_setting('tier_pub.id')::uuid,null,true,1),null::jsonb,'Publication number is not a stale lifecycle capability');
