set local role anon;
select is(public.toon_get_tier_publication(current_setting('tier_pub.id')::uuid,null,true,2)->'body'->'rows'->1->'items'->0,'null'::jsonb,'Newly hidden work becomes a non-identifying placeholder');
select ok(public.toon_get_tier_publication(current_setting('tier_pub.id')::uuid,null,true,2)::text !~ '59000000-0000-4000-8000-000000000002','Hidden work UUID is not disclosed in DTO');
