select lives_ok($$select public.toon_admin_merge_works('59000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000002',1,1,'[테스트] 동일 작품',true,(current_setting('tier_pub.merge')::jsonb->>'previewToken')::uuid,'latest_private')$$,'Draft/publication merge is atomic');
